//Generated by AI
using UnityEngine;

public class PurifierPickup : MonoBehaviour
{
    [Header("Environment")]
    [SerializeField] private GameObject pollutedEnvironment;
    [SerializeField] private GameObject restoredEnvironment;

    [Header("Accessibility")]
    [SerializeField] private SubtitleController subtitleController;
    [SerializeField] private string purificationMessage = "The environment is recovering";

    [Header("Audio")]
    [SerializeField] private AudioSource restoredEnvironmentAudio;
    [SerializeField] private AudioSource purifieractivation;
    private bool collected = false;

    // Tracks whether the player is inside the interaction range.
    private bool playerInRange = false;

    // References the purifier currently available for collection.
    public static PurifierPickup nearbyPurifier;

    private void OnTriggerEnter2D(Collider2D other)
    {
        // Register the player when entering the collection range.
        if (other.CompareTag("Player"))
        {
            playerInRange = true;
            nearbyPurifier = this;
        }
    }
    private void OnTriggerExit2D(Collider2D other)
    {
        // Clear the collectible reference when leaving the interaction area.
        if (other.CompareTag("Player"))
        {
            playerInRange = false;

            if (nearbyPurifier == this)
            {
                nearbyPurifier = null;
            }
        }
    }
    // Collects the purifier when the player explicitly interacts with it.
    public void Collect()
    {
        // Ignore repeated collection attempts.
        if (collected)
            return;

        // Require the player to be inside the interaction range.
        if (!playerInRange)
            return;

        collected = true;

        PurificationTrigger.purifierCollected = true;

        // Refresh the objective counter.
        TrashPickup[] pickups =
            FindObjectsByType<TrashPickup>(
                FindObjectsSortMode.None);

        foreach (TrashPickup pickup in pickups)
        {
            pickup.RefreshCounter();
        }

        // Display the purification message.
        if (subtitleController != null)
        {
            subtitleController.ShowSubtitle(purificationMessage);
        }

        // Hide the polluted environment.
        if (pollutedEnvironment != null)
        {
            pollutedEnvironment.SetActive(false);
        }

        // Activate the restored environment.
        if (restoredEnvironment != null)
        {
            restoredEnvironment.SetActive(true);
        }

        // Play the restored environment audio.
        if (restoredEnvironmentAudio != null)
        {
            restoredEnvironmentAudio.Play();
            purifieractivation.Play();
        }

        Debug.Log("PURIFIER COLLECTED");

        gameObject.SetActive(false);
    }
}
